\title{Universal Divisibility of Power-Difference Polynomials:\\ The Case $a^5-a$ and Its Sharpening to Modulus $30$}
\author{Aristotle}
\date{\today}

\begin{document}
\begin{abstract}
We give a complete, self-contained treatment of the classical fact that $a^5 - a$ is divisible by $5$ for every integer $a$, together with the sharpening that $a^5 - a$ is in fact divisible by $30$. The result for the prime $5$ is the case $p=5$ of Fermat's Little Theorem, which we prove from first principles via modular arithmetic and the structure of the multiplicative group of a finite field. The strengthening to $30 = 2\cdot 3\cdot 5$ is obtained by proving divisibility by each of the primes $2$, $3$, and $5$ independently and combining them through coprimality. We then place the result inside a general theory of power-difference polynomials $a^n - a$: for each exponent $n$ there is a maximal universal divisor $D(n)$, which is squarefree and equal to the product of all primes $p$ satisfying $(p-1)\mid(n-1)$. For $n=5$ this yields $D(5)=30$. We discuss the failure of the identity-map phenomenon modulo prime powers, the palindromic factorization structure of $a^n-a$ for odd $n$, and a probabilistic interpretation of the universal divisor.
\end{abstract}
\maketitle

\section{Introduction}
The statement that $a^5 - a$ is an integer multiple of $5$ for every integer $a$ is among the most familiar exercises in elementary number theory. It is a special case of a foundational result.
\begin{theorem}[Fermat's Little Theorem]\label{thm:flt}
Let $p$ be a prime. Then $a^p \equiv a \pmod p$ for every integer $a$; equivalently, $p \mid (a^p-a)$.
\end{theorem}
The case $p=5$ is a gateway to modular arithmetic, the structure of finite fields, the Chinese Remainder Theorem, and the classification of universal divisors of the family $a^n-a$. Our aims are: (1) a rigorous, motivated proof that $5 \mid (a^5-a)$; (2) the sharper $30 \mid (a^5-a)$ with a structural explanation; (3) a general framework for the universal divisibility of $a^n-a$. Throughout, $a,b,n$ denote integers, $p$ a prime, and $a\equiv b \pmod m$ means $m\mid(a-b)$.

\section{Preliminaries: Modular Arithmetic}
\begin{definition}[Congruence]
For a positive integer $m$, integers $a$ and $b$ are congruent modulo $m$, written $a\equiv b\pmod m$, if $m\mid(b-a)$. This is an equivalence relation compatible with addition and multiplication.
\end{definition}
\begin{definition}[The ring $\mathbb{Z}/m\mathbb{Z}$]
The congruence classes modulo $m$ form a commutative ring with $m$ elements, $\mathbb{Z}/m\mathbb{Z}$. Then $m \mid (a^n-a)$ for all integers $a$ iff $x^n=x$ for all $x\in\mathbb{Z}/m\mathbb{Z}$.
\end{definition}
\begin{lemma}[Finite verification]\label{lem:finite}
Let $P$ be an integer polynomial. Then $m\mid P(a)$ for all integers $a$ iff $m\mid P(r)$ for each $r\in\{0,1,\dots,m-1\}$.
\end{lemma}
\begin{proof}
Every integer $a$ is congruent modulo $m$ to exactly one $r$ in range, and $P(a)\equiv P(r)\pmod m$ by compatibility. Hence $m\mid P(a)\iff m\mid P(r)$.
\end{proof}

\section{The Prime Case: $5\mid(a^5-a)$}
\begin{theorem}\label{thm:five}
For every integer $a$, $\;5\mid(a^5-a)$; equivalently $a^5\equiv a\pmod 5$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:finite} with $m=5$ it suffices to check $r^5\equiv r\pmod 5$ for $r\in\{0,1,2,3,4\}$:
\[0^5\equiv0,\quad 1^5\equiv1,\quad 2^5=32\equiv2,\quad 3^5=243\equiv3,\quad 4^5=1024\equiv4\pmod5.\]
All hold, so $a^5\equiv a\pmod5$ for all integers $a$.
\end{proof}

We now give the structural proof revealing the mechanism.
\begin{lemma}[$\mathbb{Z}/p\mathbb{Z}$ is a field]\label{lem:field}
If $p$ is prime, every nonzero element of $\mathbb{Z}/p\mathbb{Z}$ has a multiplicative inverse, and there are no zero divisors.
\end{lemma}
\begin{proof}
For $1\le a\le p-1$, $\gcd(a,p)=1$, so by B\'ezout $ua+vp=1$, giving $ua\equiv1\pmod p$. If $ab\equiv0$ with $a\not\equiv0$, multiply by $a^{-1}$ to get $b\equiv0$.
\end{proof}
\begin{lemma}[Order divides group size]\label{lem:order}
Let $G$ be a finite abelian group of order $N$. Then $g^N=1$ for all $g\in G$.
\end{lemma}
\begin{proof}
The map $x\mapsto gx$ is a bijection of $G$, so $\prod_{x\in G}x=\prod_{x\in G}(gx)=g^N\prod_{x\in G}x$; cancelling gives $g^N=1$.
\end{proof}
\begin{proof}[Proof of Theorem~\ref{thm:flt}]
If $a\equiv0\pmod p$ then $a^p\equiv0\equiv a$. Otherwise $a\in(\mathbb{Z}/p\mathbb{Z})^\times$, a group of order $p-1$ by Lemma~\ref{lem:field}; by Lemma~\ref{lem:order}, $a^{p-1}\equiv1$, so $a^p\equiv a$.
\end{proof}
Setting $p=5$: the nonzero residues $\{1,2,3,4\}$ form a group of order $4$, so $a^4\equiv1$ and $a^5\equiv a$. Primeness is what makes $\mathbb{Z}/p\mathbb{Z}$ a field.

\section{The Sharpening: $30\mid(a^5-a)$}
\begin{lemma}[Coprime combination]\label{lem:coprime}
If $m_1,\dots,m_k$ are pairwise coprime and each $m_i\mid P$, then $\bigl(\prod_i m_i\bigr)\mid P$.
\end{lemma}
\begin{proof}
Induction on $k$ using: if $\gcd(m,m')=1$, $m\mid P$, $m'\mid P$, then $mm'\mid P$.
\end{proof}
\begin{theorem}\label{thm:thirty}
For every integer $a$, $\;30\mid(a^5-a)$.
\end{theorem}
\begin{proof}
We show divisibility by $2$, $3$, $5$ separately; as they are pairwise coprime with product $30$, Lemma~\ref{lem:coprime} concludes.
\emph{By $5$:} Theorem~\ref{thm:five}. \emph{By $3$:} $a^3\equiv a\pmod3$ (Theorem~\ref{thm:flt}), so $a^5=a^2a^3\equiv a^2a=a^3\equiv a$. \emph{By $2$:} $a^2\equiv a\pmod2$, so $a^5=(a^2)^2a\equiv a^3\equiv a$. Alternatively $a^5-a=(a-1)a(a+1)(a^2+1)$; among $a-1,a,a+1$ one is even and one is divisible by $3$.
\end{proof}
\begin{proposition}[Maximality]
No integer larger than $30$ divides $a^5-a$ for all integers $a$.
\end{proposition}
\begin{proof}
A universal divisor $D$ satisfies $D\mid(2^5-2)=30$; since $30$ is universal, it is maximal.
\end{proof}
The factorizations
\[a^5-a=(a-1)a(a+1)(a^2+1)=(a^2+1)(a^3-a)=(a^2-a)(a^3+a^2+a+1)\]
each illuminate a different divisibility; the last two are the palindromic forms.

\section{General Theory: The Universal Divisor $D(n)$}
\begin{definition}
For $n\ge1$, let $D(n)=\gcd_{a\in\mathbb{Z}}(a^n-a)$ be the largest positive integer dividing $a^n-a$ for every integer $a$.
\end{definition}
\begin{theorem}\label{thm:Dn}
For $n\ge2$, $D(n)$ is squarefree and
\[D(n)=\prod_{\substack{p\text{ prime}\\ (p-1)\mid(n-1)}}p.\]
\end{theorem}
\begin{proof}[Proof sketch]
\emph{Prime membership.} Modulo $p$: for $a\equiv0$ divisibility is automatic; for $a\not\equiv0$, $a\in(\mathbb{Z}/p\mathbb{Z})^\times$ of order $p-1$, and $a^{n-1}\equiv1$ for all such $a$ iff $(p-1)\mid(n-1)$ (necessity uses a generator of order $p-1$).
\emph{Squarefreeness.} Take $a=p$: $a^n-a=p(p^{n-1}-1)$ with $p\nmid(p^{n-1}-1)$, so $p^2\nmid(a^n-a)$. Hence each prime appears at most once.
\end{proof}
\begin{corollary}
$D(5)=30$.
\end{corollary}
\begin{proof}
Primes with $(p-1)\mid4$ are $p\in\{2,3,5\}$ (since $p-1\in\{1,2,4\}$); product $30$.
\end{proof}
\begin{example}
$D(2)=2$, $D(3)=6$, $D(5)=30$, $D(7)=42$, $D(13)=2730=2\cdot3\cdot5\cdot7\cdot13$.
\end{example}

\section{Palindromic Factorizations for Odd Exponents}
For odd $n$, $a^n-a=a(a^{n-1}-1)$ factors through symmetric factors. For $n=5$,
\[a^5-a=(a^2-a)(a^3+a^2+a+1)=(a^2+1)(a^3-a),\]
two faces of one palindromic structure; $a^3+a^2+a+1=(a+1)(a^2+1)$ is palindromic. Its values at consecutive integers share common factors assembling into $D(n)$, suggesting a systematic characterization of $D(n)$ via such palindromic factors.

\section{Failure Modulo Prime Powers}
\begin{proposition}
Let $p$ be an odd prime. There is no exponent $n>1$ with $a^n\equiv a\pmod{p^2}$ for all integers $a$.
\end{proposition}
\begin{proof}[Proof sketch]
$(\mathbb{Z}/p^2\mathbb{Z})^\times$ is cyclic of order $p(p-1)$; a universal unit identity would force $p(p-1)\mid(n-1)$, but then evaluating at $a=p$ shows the fixed-point property fails on all of $\mathbb{Z}/p^2\mathbb{Z}$.
\end{proof}

\section{Probabilistic Interpretation}
\begin{proposition}
Fix a prime $p$ and exponent $n$. If $a$ is uniform on $\{1,\dots,N\}$, then as $N\to\infty$ the proportion with $p\mid(a^n-a)$ tends to $\dfrac{\gcd(n-1,p-1)+1}{p}$, which equals $1$ exactly when $(p-1)\mid(n-1)$ and reduces to $1/p$ in the extreme case.
\end{proposition}
\begin{proof}[Proof sketch]
The qualifying residues are $a\equiv0$ plus the solutions of $a^{n-1}\equiv1$ among units, numbering $\gcd(n-1,p-1)$ in the cyclic group $(\mathbb{Z}/p\mathbb{Z})^\times$; hence $\gcd(n-1,p-1)+1$ residues out of $p$, and equidistribution gives the density.
\end{proof}

\section{Applications and Discussion}
The divisibility $5\mid(a^5-a)$ underpins primality testing, check-digit and error-detecting codes, and finite-field theory. The squarefree structure of $D(n)$ underlies Carmichael numbers and the Korselt criterion. The identity $a^p\equiv a$ states that the Frobenius endomorphism $x\mapsto x^p$ is the identity on the prime field.

\section{Conclusion}
Reducing an infinite family of integer statements to a finite modular check, then explaining that check through the multiplicative group of a field, turns the elementary fact $30\mid(a^5-a)$ into a theorem with a transparent cause and a sweeping generalization: for every exponent $n$, $D(n)$ is the squarefree product of the primes $p$ with $(p-1)\mid(n-1)$.

\end{document}

