"""Empirical discovery of the universal divisor D(n) via iterated gcd."""
from __future__ import annotations
from math import gcd
from functools import reduce
from typing import List

def universal_divisor_empirical(n: int, a_max: int = 300) -> int:
    """Estimate D(n) = gcd over a of (a^n - a) using a in {2,...,a_max}."""
    vals: List[int] = [a ** n - a for a in range(2, a_max + 1)]
    return reduce(gcd, vals)

def convergence_trace(n: int, a_max: int = 12) -> List[int]:
    """Show how the running gcd stabilises to D(n)."""
    running = 0
    trace: List[int] = []
    for a in range(2, a_max + 1):
        running = gcd(running, a ** n - a)
        trace.append(running)
    return trace

if __name__ == "__main__":
    for n in (2, 3, 5, 7, 13):
        print(f"D({n}) = {universal_divisor_empirical(n)}   trace n={n}: {convergence_trace(n)}")

"""Finite residue verification that m | (a^n - a) for all integers a."""
from __future__ import annotations

def divides_all(m: int, n: int) -> bool:
    """True iff m divides a^n - a for every integer a (check residues 0..m-1)."""
    return all((pow(r, n, m) - r) % m == 0 for r in range(m))

def largest_universal(n: int, cap: int = 5000) -> int:
    """Largest m <= cap with m | (a^n - a) for all a (should equal D(n))."""
    best = 1
    for m in range(1, cap + 1):
        if divides_all(m, n):
            best = m
    return best

if __name__ == "__main__":
    print("5  | a^5 - a :", divides_all(5, 5))
    print("30 | a^5 - a :", divides_all(30, 5))
    print("31 | a^5 - a :", divides_all(31, 5))
    print("largest universal divisor for n=5:", largest_universal(5, 200))

"""Direct table verification of a^5 == a (mod 5) over all residues."""
from __future__ import annotations
from typing import List, Tuple

def fifth_power_table(p: int = 5) -> List[Tuple[int, int, bool]]:
    """Return (r, r^p mod p, r^p==r) for each residue r mod p."""
    return [(r, pow(r, p, p), pow(r, p, p) == r % p) for r in range(p)]

if __name__ == "__main__":
    for r, rp, ok in fifth_power_table(5):
        print(f"{r}^5 = {r**5:>5}  ≡ {rp} (mod 5)   fixed: {ok}")

